-- Generated by generate_location_update_sql.py from /Users/jeffkungu/Desktop/PMS_Requests
-- 28 acceptance requests (9522-9549), 1838 line items.
--
-- Sets tb_DCC_LN.locationName so the detailed-view Excel export of each request lists the file's locations in
-- the file's sequence: file row N -> the request's N-th line by tb_DCC_LN.recordNo (the export's order).
-- A request is updated only if ALL of these hold, otherwise it's left alone and reported (ok = 0):
--   * the database has exactly as many lines as the file,
--   * every file row's PO Number / PO Line No. / UPL Line No. equals that of the line it lands on.
-- Runs in one transaction; uses session-only TEMPORARY tables (nothing is created permanently).
-- Run the whole file in one session:  mysql -u root -p ALM_ZAIN_KSA < update_dcc_ln_locations.sql > update_dcc_ln_locations.out

SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS tmp_pms_file, tmp_pms_line, tmp_pms_check;

CREATE TEMPORARY TABLE tmp_pms_file (
  dccId        VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  seq          INT NOT NULL,
  poNumber     VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  poLine       VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  uplLine      VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  locationName VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  fileName     VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  PRIMARY KEY (dccId, seq)
);


-- The requests' lines in export order (recordNo), numbered 1..n per request.
CREATE TEMPORARY TABLE tmp_pms_line (PRIMARY KEY (dccId, seq)) AS
SELECT ln.recordNo, ln.dccId,
       ROW_NUMBER() OVER (PARTITION BY ln.dccId ORDER BY ln.recordNo) AS seq,
       ln.lineNumber, ln.uplLineNumber, ln.locationName AS oldLocation, d.poNumber AS dccPoNumber
FROM   tb_DCC_LN ln JOIN tb_DCC d ON d.recordNo = ln.dccId
WHERE  ln.dccId IN ('9522');

-- Per-request checks.
CREATE TEMPORARY TABLE tmp_pms_check (PRIMARY KEY (dccId)) AS
SELECT f.dccId, MAX(f.fileName) AS fileName, COUNT(*) AS fileRows,
       SUM(l.recordNo IS NULL) AS rowsWithoutLine,
       SUM(l.recordNo IS NOT NULL AND (l.dccPoNumber <> f.poNumber OR TRIM(l.lineNumber) <> f.poLine
                                       OR TRIM(COALESCE(l.uplLineNumber, '')) <> f.uplLine)) AS lineMismatches,
       CAST(0 AS SIGNED) AS dbLines, 0 AS ok
FROM   tmp_pms_file f LEFT JOIN tmp_pms_line l ON l.dccId = f.dccId AND l.seq = f.seq
GROUP  BY f.dccId;

UPDATE tmp_pms_check c
JOIN  (SELECT dccId, COUNT(*) AS n FROM tmp_pms_line GROUP BY dccId) n ON n.dccId = c.dccId
SET    c.dbLines = n.n;

UPDATE tmp_pms_check
SET    ok = (fileRows = dbLines AND rowsWithoutLine = 0 AND lineMismatches = 0);

SELECT c.dccId AS requestNo, c.fileName, d.status AS requestStatus, c.fileRows, c.dbLines,
       c.rowsWithoutLine, c.lineMismatches, c.ok
FROM   tmp_pms_check c LEFT JOIN tb_DCC d ON d.recordNo = c.dccId
ORDER  BY CAST(c.dccId AS UNSIGNED);

-- The update (only requests with ok = 1).
UPDATE tb_DCC_LN ln
JOIN   tmp_pms_line l  ON l.recordNo = ln.recordNo
JOIN   tmp_pms_file f  ON f.dccId = l.dccId AND f.seq = l.seq
JOIN   tmp_pms_check c ON c.dccId = l.dccId AND c.ok = 1
SET    ln.locationName = f.locationName;

-- After: per request, how many lines now differ from the file in export order (must be 0 for ok = 1 requests).
SELECT l.dccId AS requestNo, COUNT(*) AS linesChecked,
       SUM(ln.locationName <> f.locationName) AS linesDifferentFromFile,
       SUM(l.oldLocation <> f.locationName) AS linesChanged
FROM   tmp_pms_line l
JOIN   tb_DCC_LN ln ON ln.recordNo = l.recordNo
JOIN   tmp_pms_file f ON f.dccId = l.dccId AND f.seq = l.seq
GROUP  BY l.dccId
ORDER  BY CAST(l.dccId AS UNSIGNED);

COMMIT;

DROP TEMPORARY TABLE IF EXISTS tmp_pms_file, tmp_pms_line, tmp_pms_check;
